{
  "findings": [
    {
      "check_id": "CKV_AWS_144",
      "title": "Launch Template missing metadata options (IMDSv2)",
      "resource": "aws_launch_template.changeme_simple_asg_launch_template_nlb",
      "severity": "MEDIUM",
      "explanation": "The launch template does not configure `metadata_options` to enforce IMDSv2 (`http_tokens = \"required\"`). Without this, instances can be vulnerable to Server-Side Request Forgery (SSRF) attacks that steal IAM credentials via the Instance Metadata Service."
    }
  ],
  "patched_code": "resource \"aws_launch_template\" \"changeme_simple_asg_launch_template_nlb\" {\n  name                   = \"changeme-simple-asg-launch-template-nlb\"\n  image_id               = data.aws_ami.changeme_amazon_nlb_ami.id\n  instance_type          = \"t2.micro\"\n  vpc_security_group_ids = [aws_security_group.changeme_nlb_aws_security_group.id]\n  user_data              = filebase64(\"${path.module}/user_data.sh\")\n\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n}",
  "fix_summary": "Added a `metadata_options` block to the `aws_launch_template` resource to enforce IMDSv2 by setting `http_tokens = \"required\"`, mitigating SSRF risks associated with the Instance Metadata Service."
}
